import React, { useState, useRef, useEffect } from 'react';
import { 
  ArrowUp, Paperclip, Smile, Send, MoreVertical, 
  Video, Phone, User, Star, Pin, X, 
  Image, File, Download, Trash2, Copy,
  CheckCheck, Clock, Mic, VolumeX
} from 'lucide-react';

const ChatWindow = ({ message, onClose }) => {
  const [inputMessage, setInputMessage] = useState('');
  const [messages, setMessages] = useState([
    { id: 1, text: 'Bonjour, j\'ai une question concernant ma commande #ORD-001', time: '10:30', sender: 'user', status: 'read' },
    { id: 2, text: 'Bonjour John, comment puis-je vous aider avec votre commande?', time: '10:32', sender: 'me', status: 'read' },
    { id: 3, text: 'Je voudrais savoir quand elle sera expédiée', time: '10:33', sender: 'user', status: 'read' },
    { id: 4, text: 'Votre commande sera expédiée demain matin. Vous recevrez un email de confirmation.', time: '10:35', sender: 'me', status: 'delivered' },
    { id: 5, text: 'Parfait, merci beaucoup pour votre rapidité!', time: '10:36', sender: 'user', status: 'read' },
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const messagesEndRef = useRef(null);
  const fileInputRef = useRef(null);

  // Auto-scroll to bottom
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Simuler la frappe
  useEffect(() => {
    if (isTyping) {
      const timer = setTimeout(() => setIsTyping(false), 2000);
      return () => clearTimeout(timer);
    }
  }, [isTyping]);

  const handleSend = () => {
    if (inputMessage.trim()) {
      const newMessage = {
        id: messages.length + 1,
        text: inputMessage,
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        sender: 'me',
        status: 'sent'
      };
      setMessages([...messages, newMessage]);
      setInputMessage('');
      setIsTyping(true);

      // Simuler une réponse automatique
      setTimeout(() => {
        const responses = [
          "Je vous remercie pour votre message.",
          "Je vais vérifier cela pour vous.",
          "Pouvez-vous me donner plus de détails?",
          "J'ai bien noté votre demande."
        ];
        const randomResponse = responses[Math.floor(Math.random() * responses.length)];
        setMessages(prev => [...prev, {
          id: prev.length + 2,
          text: randomResponse,
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          sender: 'user',
          status: 'read'
        }]);
      }, 1500);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleFileUpload = () => {
    fileInputRef.current.click();
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'sent': return <Clock className="h-3 w-3 text-neutral-400" />;
      case 'delivered': return <CheckCheck className="h-3 w-3 text-neutral-400" />;
      case 'read': return <CheckCheck className="h-3 w-3 text-blue-500" />;
      default: return null;
    }
  };

  return (
    <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/40 dark:border-neutral-800/60 h-[600px] flex flex-col overflow-hidden">
      {/* Header */}
      <div className="p-5 border-b border-neutral-200/60 dark:border-neutral-800/60 bg-white/50 dark:bg-neutral-900/50">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <button
              onClick={onClose}
              className="md:hidden p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-colors"
            >
              <X className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
            </button>
            <div className="relative">
              <div className={`h-12 w-12 rounded-2xl bg-gradient-to-r ${message?.avatarColor || 'from-primary-500 to-secondary-500'} flex items-center justify-center shadow-lg`}>
                <span className="text-white font-bold text-xl">
                  {message?.sender.charAt(0) || 'U'}
                </span>
              </div>
              {message?.online && (
                <div className="absolute -bottom-1 -right-1 h-4 w-4 bg-green-500 rounded-full border-2 border-white dark:border-neutral-900"></div>
              )}
            </div>
            <div>
              <div className="flex items-center space-x-2">
                <h3 className="font-bold text-neutral-900 dark:text-white text-lg">
                  {message?.sender || 'Utilisateur'}
                </h3>
                {message?.verified && (
                  <span className="h-5 w-5 bg-blue-500 rounded-full flex items-center justify-center">
                    <CheckCheck className="h-3 w-3 text-white" />
                  </span>
                )}
              </div>
              <div className="flex items-center space-x-3">
                <p className="text-sm text-neutral-600 dark:text-neutral-400 flex items-center">
                  <span className={`h-2 w-2 rounded-full mr-2 ${
                    message?.online ? 'bg-green-500 animate-pulse' : 'bg-neutral-400'
                  }`}></span>
                  {message?.online ? 'En ligne' : 'Hors ligne'}
                </p>
                <span className="text-xs px-2 py-1 rounded-full bg-primary-500/10 text-primary-600 dark:text-primary-400">
                  {message?.status || 'Client'}
                </span>
              </div>
            </div>
          </div>

          <div className="flex items-center space-x-2">
            <button className="p-3 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-2xl transition-all duration-300 hover:scale-105">
              <Phone className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
            </button>
            <button className="p-3 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-2xl transition-all duration-300 hover:scale-105">
              <Video className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
            </button>
            <button className="p-3 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-2xl transition-all duration-300 hover:scale-105">
              <Star className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
            </button>
            <div className="relative">
              <button
                onClick={() => setMenuOpen(!menuOpen)}
                className="p-3 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-2xl transition-all duration-300"
              >
                <MoreVertical className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
              </button>
              {menuOpen && (
                <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-neutral-800 rounded-2xl shadow-2xl border border-neutral-200 dark:border-neutral-700 overflow-hidden z-10 animate-fadeIn">
                  {[
                    { icon: <Pin className="h-4 w-4" />, label: 'Épingler' },
                    { icon: <VolumeX className="h-4 w-4" />, label: 'Silencieux' },
                    { icon: <Copy className="h-4 w-4" />, label: 'Copier l\'ID' },
                    { icon: <Trash2 className="h-4 w-4" />, label: 'Supprimer', danger: true },
                  ].map((item, index) => (
                    <button
                      key={index}
                      className={`w-full px-4 py-3 flex items-center space-x-3 hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors ${
                        item.danger ? 'text-red-500' : 'text-neutral-700 dark:text-neutral-300'
                      }`}
                    >
                      {item.icon}
                      <span>{item.label}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-5 scrollbar-thin scrollbar-thumb-neutral-300 dark:scrollbar-thumb-neutral-700 scrollbar-track-transparent">
        <div className="space-y-4">
          {messages.map((msg) => (
            <div
              key={msg.id}
              className={`flex ${msg.sender === 'me' ? 'justify-end' : 'justify-start'} animate-fadeInUp`}
            >
              <div className={`max-w-[70%] rounded-3xl p-4 relative transition-all duration-300 hover:scale-[1.02] ${
                msg.sender === 'me'
                  ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none shadow-lg shadow-primary-500/25'
                  : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-white rounded-bl-none'
              }`}>
                <p className="text-sm md:text-base leading-relaxed">{msg.text}</p>
                <div className={`flex items-center justify-between mt-3 ${
                  msg.sender === 'me' ? 'text-white/80' : 'text-neutral-500'
                }`}>
                  <span className="text-xs">{msg.time}</span>
                  {msg.sender === 'me' && (
                    <div className="flex items-center space-x-1">
                      {getStatusIcon(msg.status)}
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}

          {isTyping && (
            <div className="flex justify-start animate-fadeIn">
              <div className="bg-neutral-100 dark:bg-neutral-800 rounded-3xl rounded-bl-none p-4">
                <div className="flex space-x-2">
                  <div className="h-2 w-2 bg-neutral-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                  <div className="h-2 w-2 bg-neutral-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                  <div className="h-2 w-2 bg-neutral-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                </div>
              </div>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Input Area */}
      <div className="p-5 border-t border-neutral-200/60 dark:border-neutral-800/60 bg-white/50 dark:bg-neutral-900/50">
        {/* Options */}
        <div className="flex items-center justify-between mb-3 px-2">
          <div className="flex items-center space-x-3">
            <button
              onClick={handleFileUpload}
              className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-all duration-300 hover:scale-110"
            >
              <Paperclip className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
            </button>
            <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-all duration-300 hover:scale-110">
              <Image className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
            </button>
            <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-all duration-300 hover:scale-110">
              <File className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
            </button>
            <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-all duration-300 hover:scale-110">
              <Mic className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
            </button>
          </div>
          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-all duration-300 hover:scale-110">
            <Smile className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
          </button>
        </div>

        {/* Input */}
        <div className="relative group">
          <input
            type="text"
            value={inputMessage}
            onChange={(e) => setInputMessage(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Écrivez votre message..."
            className="w-full pl-5 pr-16 py-4 bg-white dark:bg-neutral-800 border-2 border-neutral-200/60 dark:border-neutral-700/60 rounded-2xl text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:border-primary-500 focus:ring-4 focus:ring-primary-500/20 transition-all duration-300"
          />
          <button
            onClick={handleSend}
            disabled={!inputMessage.trim()}
            className={`absolute right-3 top-1/2 -translate-y-1/2 p-3 rounded-xl transition-all duration-300 ${
              inputMessage.trim()
                ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg shadow-primary-500/25 hover:scale-110'
                : 'bg-neutral-200 dark:bg-neutral-700 text-neutral-400 cursor-not-allowed'
            }`}
          >
            <Send className="h-5 w-5" />
          </button>
        </div>

        {/* File input hidden */}
        <input
          type="file"
          ref={fileInputRef}
          className="hidden"
          multiple
        />
      </div>
    </div>
  );
};

export default ChatWindow;
